import assert from 'node:assert/strict';
import test from 'node:test';
import { fixture } from './worker/test/managed-runtime-fixture.mjs';
const { snapshot } = await import('./worker/providers.ts');
test('unified GMI selectors', async t => {
 const source=structuredClone(snapshot.providers.find(p=>p.id==='gmi'));
 const f=await fixture(t,{providerId:'gmi',pooled:false,configure(p){Object.assign(p,source)}});
 f.env.GMI_API_KEY='synthetic-gmi-key';
 f.upstream=()=>Response.json({model:'deepseek-ai/DeepSeek-V4-Pro',choices:[{message:{role:'assistant',content:'ok'},finish_reason:'stop'}],usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}});
 const response=await f.call('/v1/chat/completions',{model:'gmi/deepseek-ai/DeepSeek-V4-Pro',messages:[{role:'user',content:'synthetic'}]});
 assert.equal(response.status,200); await response.arrayBuffer(); await f.drain();
});

